"""2026-10-14 (PI request, item 5): one-line-per-study sheet for the 21 included records that look like pure narrative, perspective or doctrinal papers, so the PI can rule in one pass which to exclude under E05
(no systematic search or selection and no stated data or method, criterion 3; precedent S340, S513, S1117, S264) and which to keep. They are the NONE list minus S480 (S079, S320, S326, S429, S430, S436, S440, S466, S479, S482),
plus the rows left over from open items A11 and A12 (S181, S335, S236, S281, S260, S267, S288, S203, S199, S243, S246). No row is changed by this script: the researcher columns are blank and `ai_suggestion` is only a suggestion.
Facts come from the extraction rows, from the full texts in the researcher's Drive where one is cited, and, for S429 and S466, from a read of the Drive copies on 2026-10-14 (S429 about the first 30,000 of 68,000 characters, covering abstract, introduction, methods and results; S466 the abstract,
introduction, methods, the one tariff passage and keyword counts of the rest). The sheet has the same columns as NARROW_SCOPE_RECHECK_OF_INCLUDES_2026-10-13.csv, so apply_a16_adjudications.py can take the filled copy. Writes 02_screening/full_text/E05_RECHECK_21_RECORDS_2026-10-14.{csv,md}.
Run from legal-last-mile-systematic-review/."""
import csv, sys
csv.field_size_limit(sys.maxsize)
ED = '03_extraction/extracted_data/extraction_database.csv'
OUT = '02_screening/full_text/E05_RECHECK_21_RECORDS_2026-10-14'
# (study, group, what the paper is, primary empirical data?, systematic search or selection?, AI suggestion, reason)
ROWS = [
 ('S320', 'NONE list', 'Narrative review of water kiosks for the urban poor in Africa (4 pages)', 'No (cites other studies\' figures)', 'No (no search, databases or selection stated)', 'E05', 'same ground as S340; a service model (kiosks), not a legal rule'),
 ('S326', 'NONE list', 'Narrative "survey of the evidence" on whether utility ownership matters for social outcomes', 'No', 'No (full text confirms: no search, selection, protocol or appraisal)', 'E05', 'ownership is in scope, but no method; findings remain citable as background'),
 ('S436', 'NONE list', 'Documental synthesis of Mexican sanitation strategies read through the Community Capitals Framework', 'Secondary documents only', 'No', 'E05', 'framework-driven documentary synthesis, no stated selection'),
 ('S440', 'NONE list', 'Annual Review narrative review of US drinking-water safety, access and consumption disparities', 'No', 'No (the method text says "narrative/systematic" but states no search)', 'E05', 'regulation (Lead and Copper Rule) is background, no access outcome tested'),
 ('S482', 'NONE list', 'Conceptual review: why home-centred infrastructure fails people without a fixed dwelling ("dwelling-centric" provision)', 'No', 'No', 'E05', 'conceptual; unlike S1168 it reports no search'),
 ('S236', 'A11/A12', 'Colombian "differential schemes" and the urban-rural divide: literature plus the authors\' field observations and testimonies', 'Informal (field observations, no stated method)', 'No', 'E05', 'no stated method for the observations'),
 ('S260', 'A11/A12', 'Nine-year critical review of SDG 6 progress in Nigeria (Ogunbode et al. 2025)', 'No', 'No (no document count, no appraisal)', 'E05', 'also national-progress macro-governance, so E03 is the alternative ground'),
 ('S203', 'A11/A12', 'Doctrinal legal-historical analysis of Spanish water legislation (1813 to 2019) with a SWOT', 'No (statutes only)', 'n/a', 'E05', 'exclusion criterion 1: doctrinal commentary without access evidence'),
 ('S243', 'A11/A12', 'NGO-authored description of two community water projects in Rajasthan, India', 'Self-reported project results, no stated method', 'No', 'E05', 'project description; community delivery rather than a legal rule (E03 alternative)'),
 ('S246', 'A11/A12', 'Design-stage description of the Projeto Vida no Vale governance model (Minas Gerais, Brazil)', 'No (a proposal; no outcomes)', 'No', 'E05', 'no outcomes (criterion 4) as well as no method'),
 ('S079', 'NONE list', 'WIREs focus article on US colonias: underbounding, annexation and utility rules (Wutich et al.)', 'No (synthesises empirical, legal and policy literature)', 'No', 'PI call (high topical fit)', 'fails criterion 3 on method like S340, but the mechanisms (underbounding, annexation, service-area rules) are squarely in scope; mechanism_certainty 3'),
 ('S430', 'NONE list', 'Critical review of SDG 6 progress in Nigeria 2016-2024 (Ogunbode 2026)', 'No', 'Partly: targeted search of Google Scholar and agency sources with keywords and inclusion criteria, content analysis; no flow diagram, no appraisal (from a text search of the Drive copy)', 'PI call (E03 or E05)', 'national-progress macro-governance (infrastructure investment, governance inefficiency); method is weaker than S1168 and S466'),
 ('S479', 'NONE list', 'Research and policy-agenda review comparing how seven Southwestern primacy agencies define and regulate unregulated water users', 'Documentary: statutes and regulations compared across seven agencies', 'No search; the agencies are a fixed set', 'PI call (lean E05)', 'the rule is the subject (in scope) but it reports no access outcome (criterion 4); a legal-text comparison'),
 ('S267', 'A11/A12', 'Perspective article: governance failure and corruption in South African municipal water, eight purposively chosen municipalities (Matimolane 2026)', 'Documentary (audit reports and press) on eight cases', 'Purposive case selection stated, no search', 'PI call (lean E05)', 'labelled a perspective, like S1117; corruption and procurement are governance background rather than an access rule (E03 alternative)'),
 ('S199', 'A11/A12', 'Doctrinal comparison of Spanish regional laws protecting the right to water for families at risk of exclusion (cut-off protocols, minimum volumes)', 'No (statutory texts; no outcome data)', 'n/a', 'PI call (lean E05)', 'squarely in scope on the rule (disconnection protections) but doctrinal with no access evidence (exclusion criterion 1)'),
 ('S429', 'NONE list', 'Narrative synthesis of barriers to menstrual hygiene in African prisons (Rasweswe et al. 2025)', 'No (9 records, thematic analysis)', 'Yes, in part: six databases, keywords, inclusion criteria, independent selection by all authors, data charting; no flow diagram or appraisal', 'E03 (fails the narrow scope; not moved to AMSTAR 2)', 'population is incarcerated women and the barrier is supply and facilities in prison, with policy only as background: the same ground as Aluko 2022'),
 ('S466', 'NONE list', 'Adaptive capacity in water governance for SDG 6, Nigeria with Ghana and Kenya as comparators (Fadeyi et al. 2025)', 'No (one cited 193-household survey)', 'Yes: four databases and three search engines, 223 documents, inclusion criteria, PRISMA flow diagram, narrative synthesis', 'E03 (fails the narrow scope; not moved to AMSTAR 2)', 'macro-governance and climate-adaptation framing (OECD principles); over-regulation and tariff structure get one sentence; the same ground as S348 and S969'),
 ('S181', 'A11/A12', 'Bayesian-network model of water and sanitation indicators in 101 developing countries (Dondeynaz et al. 2013)', 'Yes (secondary national indicators, modelled)', 'n/a (not a review)', 'keep for E05; scope flag (E03?)', 'governance effectiveness is one of the model\'s variables, not a tested rule'),
 ('S335', 'A11/A12', 'Targeted literature and documentary review with institutional data, Piura, Peru (Sanchez Ruiz et al. 2025)', 'Yes (institutional coverage and service-hours data)', 'Stated but not systematic: 40 peer-reviewed documents, March-August 2025', 'keep', 'documented selection and data; overlapping mandates are the studied mechanism'),
 ('S281', 'A11/A12', 'Systems-thinking model of SDG 6.5.1 implementation in Ethiopia (Dinsa et al. 2026)', 'Yes (six-expert consultation, causal-loop model)', 'Narrative literature review used to build the model; no search stated', 'keep for E05; scope flag (E03/E04?)', 'integrated water resources management, not household access'),
 ('S288', 'A11/A12', 'Baghdad unregulated urban sprawl, services and quality of life: 300-household survey, 20 stakeholders, GIS (Ebraheem et al. 2024)', 'Yes (but planned methods not carried out and tables do not reconcile; MMAT 1 of 5)', 'n/a', 'keep for E05; scope flag (E03?)', 'unregulated sprawl is the exposure; weakly reported'),
]
ed = {r['study_id']: r for r in csv.DictReader(open(ED, newline='', encoding='utf-8'))}
assert len(ROWS) == 21 and len({r[0] for r in ROWS}) == 21
fields = ['study_id', 'record_id', 'group', 'governance_flags_true', 'citation', 'country', 'study_design', 'risk_of_bias_tool', 'sample_size', 'effect_or_finding_as_extracted',
          'ai_suggestion', 'ai_reason', 'researcher_decision (include/exclude)', 'researcher_exclusion_code (E01-E12)', 'researcher_comment']
with open(OUT + '.csv', 'w', newline='', encoding='utf-8') as f:
    w = csv.DictWriter(f, fieldnames=fields, lineterminator='\n'); w.writeheader()
    for sid, grp, what, prim, sysm, sug, why in ROWS:
        e = ed[sid]
        w.writerow({'study_id': sid, 'record_id': e['record_id'], 'group': grp, 'citation': e['citation'], 'country': e['country'], 'study_design': e['study_design'][:200], 'risk_of_bias_tool': e['risk_of_bias_tool'][:60],
                    'sample_size': e['sample_size'][:120], 'effect_or_finding_as_extracted': e['effect_estimate'][:500], 'ai_suggestion': sug, 'ai_reason': why})
L = ['# E05 recheck of 21 narrative, perspective and doctrinal includes (2026-10-14)', '',
     "For the PI's one-pass ruling (request of 2026-10-14, item 5). The ground is criterion 3, no systematic search or selection and no stated data or method (E05), as for S340, S513, S1117 and S264; S429 and S466 were also checked against the narrow scope (criteria 2 and 4). "
     "Nothing was changed: `ai_suggestion` is a suggestion, and the researcher columns of `E05_RECHECK_21_RECORDS_2026-10-14.csv` are blank (same layout as the A24 recheck sheet, so `apply_a16_adjudications.py` takes the filled copy). "
     "Sources: the extraction rows, the full texts the researcher supplied, and for S429 and S466 a partial read of the Drive copies (S429 abstract, introduction, methods and results; S466 abstract, introduction, methods and keyword counts) on 2026-10-14.", '',
     '| Study | What the paper is | Primary empirical data? | Systematic search or selection? | AI suggestion |', '|---|---|---|---|---|']
L += [f'| {sid} | {what} | {prim} | {sysm} | **{sug}**: {why} |' for sid, grp, what, prim, sysm, sug, why in ROWS]
L += ['', '**Counts of the suggestions:** E05 ' + str(sum(r[5] == 'E05' for r in ROWS)) + '; PI call ' + str(sum(r[5].startswith('PI call') for r in ROWS)) + '; E03 (S429, S466) ' + str(sum(r[5].startswith('E03') for r in ROWS)) + '; keep ' + str(sum(r[5].startswith('keep') for r in ROWS)) + '.', '',
      'No row has an effect-size row or a linked report, so the exclusion route of `resolve_a16_pending_reversals.py` accepts all 21.']
open(OUT + '.md', 'w', encoding='utf-8').write('\n'.join(L) + '\n')
print('wrote', OUT + '.csv and .md')
